#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <algorithm>
#include <cstdint>
#include <functional>

// Rate limiter to prevent brute-force attacks
class RateLimiter {
private:
    struct BucketEntry {
        int32_t tokens;
        int64_t last_refill_time;
        std::string client_id;
    };

    std::mutex mtx_;
    std::unordered_map<std::string, BucketEntry> buckets_;
    static constexpr int32_t MAX_TOKENS = 100;
    static constexpr int32_t REFILL_RATE = 10; // tokens per second
    static constexpr int32_t PENALTY_COST = 30;

public:
    // Returns remaining tokens after consumption
    int32_t consume(const std::string& client_id, int32_t cost, int64_t current_time) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = buckets_.find(client_id);
        if (it == buckets_.end()) {
            buckets_[client_id] = {MAX_TOKENS, current_time, client_id};
            it = buckets_.find(client_id);
        }

        // Refill tokens based on elapsed time
        int64_t elapsed = current_time - it->second.last_refill_time;
        int32_t refill = static_cast<int32_t>(elapsed * REFILL_RATE);
        it->second.tokens = std::min(MAX_TOKENS, it->second.tokens + refill);
        it->second.last_refill_time = current_time;

        // Consume tokens
        it->second.tokens -= cost;
        return it->second.tokens;
    }

    void apply_penalty(const std::string& client_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = buckets_.find(client_id);
        if (it != buckets_.end()) {
            it->second.tokens -= PENALTY_COST;
        }
    }

    bool is_allowed(const std::string& client_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = buckets_.find(client_id);
        if (it == buckets_.end()) return true;
        // Check if client has positive token balance
        return it->second.tokens >= 0;
    }
};

// Session store with security controls
class SessionStore {
private:
    struct Session {
        std::string user_id;
        std::string role;
        int32_t privilege_level;
        int64_t created_at;
        int64_t expires_at;
        bool is_locked;
    };

    std::mutex mtx_;
    std::unordered_map<std::string, Session> sessions_;

public:
    bool create_session(const std::string& token, const std::string& user_id,
                       const std::string& role, int32_t priv_level,
                       int64_t created_at, int64_t ttl) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (sessions_.count(token)) return false;
        sessions_[token] = {user_id, role, priv_level, created_at, created_at + ttl, false};
        return true;
    }

    bool validate_session(const std::string& token, int64_t current_time) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(token);
        if (it == sessions_.end()) return false;
        if (it->second.is_locked) return false;
        if (current_time > it->second.expires_at) return false;
        return true;
    }

    int32_t get_privilege_level(const std::string& token) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(token);
        if (it == sessions_.end()) return -1;
        return it->second.privilege_level;
    }

    std::string get_role(const std::string& token) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(token);
        if (it == sessions_.end()) return "";
        return it->second.role;
    }

    void lock_session(const std::string& token) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(token);
        if (it != sessions_.end()) {
            it->second.is_locked = true;
        }
    }

    bool elevate_privilege(const std::string& token, int32_t new_level) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(token);
        if (it == sessions_.end()) return false;
        if (it->second.is_locked) return false;
        it->second.privilege_level = new_level;
        return true;
    }
};

// Access control decision engine
class AccessController {
private:
    SessionStore& sessions_;
    RateLimiter& limiter_;

    struct ResourcePolicy {
        std::string resource_path;
        int32_t min_privilege;
        std::vector<std::string> allowed_roles;
        uint32_t max_request_cost;
    };

    std::vector<ResourcePolicy> policies_;

public:
    AccessController(SessionStore& sessions, RateLimiter& limiter)
        : sessions_(sessions), limiter_(limiter) {
        // Define resource policies
        policies_.push_back({"/api/public", 0, {"user", "admin", "service"}, 1});
        policies_.push_back({"/api/user", 1, {"user", "admin"}, 5});
        policies_.push_back({"/api/admin", 5, {"admin"}, 10});
        policies_.push_back({"/api/admin/elevate", 8, {"admin"}, 20});
        policies_.push_back({"/api/system", 10, {"service"}, 50});
    }

    struct AccessDecision {
        bool allowed;
        std::string reason;
        int32_t remaining_tokens;
    };

    AccessDecision check_access(const std::string& session_token,
                               const std::string& resource_path,
                               const std::string& client_ip,
                               int64_t current_time) {
        // Step 1: Rate limit check
        if (!limiter_.is_allowed(client_ip)) {
            return {false, "rate_limited", 0};
        }

        // Step 2: Session validation
        if (!sessions_.validate_session(session_token, current_time)) {
            limiter_.apply_penalty(client_ip);
            return {false, "invalid_session", 0};
        }

        // Step 3: Find matching policy
        const ResourcePolicy* matching_policy = nullptr;
        for (const auto& policy : policies_) {
            if (resource_path.find(policy.resource_path) == 0) {
                if (!matching_policy || 
                    policy.resource_path.length() > matching_policy->resource_path.length()) {
                    matching_policy = &policy;
                }
            }
        }

        if (!matching_policy) {
            return {false, "no_policy", 0};
        }

        // Step 4: Privilege level check
        int32_t user_priv = sessions_.get_privilege_level(session_token);
        if (user_priv < matching_policy->min_privilege) {
            return {false, "insufficient_privilege", 0};
        }

        // Step 5: Role check
        std::string user_role = sessions_.get_role(session_token);
        bool role_match = false;
        for (const auto& allowed_role : matching_policy->allowed_roles) {
            if (user_role == allowed_role) {
                role_match = true;
                break;
            }
        }
        if (!role_match) {
            return {false, "role_denied", 0};
        }

        // Step 6: Consume rate limit tokens
        int32_t remaining = limiter_.consume(client_ip, 
            static_cast<int32_t>(matching_policy->max_request_cost), current_time);

        return {true, "granted", remaining};
    }
};

// Privilege escalation service
class PrivilegeService {
private:
    SessionStore& sessions_;
    RateLimiter& limiter_;
    AccessController& access_ctrl_;

    static constexpr int32_t ESCALATION_THRESHOLD = 8;

public:
    PrivilegeService(SessionStore& sessions, RateLimiter& limiter, AccessController& ac)
        : sessions_(sessions), limiter_(limiter), access_ctrl_(ac) {}

    struct EscalationResult {
        bool success;
        std::string message;
        int32_t new_level;
    };

    EscalationResult request_elevation(const std::string& session_token,
                                       int32_t requested_level,
                                       const std::string& client_ip,
                                       int64_t current_time) {
        // First check access to the elevation endpoint
        auto decision = access_ctrl_.check_access(
            session_token, "/api/admin/elevate", client_ip, current_time);

        if (!decision.allowed) {
            return {false, "access_denied: " + decision.reason, 0};
        }

        // Validate requested level bounds
        int32_t current_level = sessions_.get_privilege_level(session_token);

        // Security check: requested level must not exceed current + 2
        // This prevents jumping from level 8 directly to level 100
        uint32_t max_elevation = static_cast<uint32_t>(current_level) + 2;
        if (static_cast<uint32_t>(requested_level) > max_elevation) {
            limiter_.apply_penalty(client_ip);
            return {false, "elevation_too_high", current_level};
        }

        // Apply the elevation
        if (sessions_.elevate_privilege(session_token, requested_level)) {
            return {true, "elevated", requested_level};
        }

        return {false, "elevation_failed", current_level};
    }
};

// Main request handler
struct Request {
    std::string session_token;
    std::string resource_path;
    std::string client_ip;
    int64_t timestamp;
    int32_t requested_priv_level; // for elevation requests
};

struct Response {
    int status_code;
    std::string body;
};

class RequestHandler {
private:
    SessionStore sessions_;
    RateLimiter limiter_;
    AccessController access_ctrl_;
    PrivilegeService priv_service_;

public:
    RequestHandler() 
        : access_ctrl_(sessions_, limiter_),
          priv_service_(sessions_, limiter_, access_ctrl_) {}

    // For testing: create a session
    void setup_session(const std::string& token, const std::string& user_id,
                      const std::string& role, int32_t priv_level,
                      int64_t created_at, int64_t ttl) {
        sessions_.create_session(token, user_id, role, priv_level, created_at, ttl);
    }

    Response handle_request(const Request& req) {
        if (req.resource_path == "/api/admin/elevate") {
            auto result = priv_service_.request_elevation(
                req.session_token, req.requested_priv_level,
                req.client_ip, req.timestamp);

            if (result.success) {
                return {200, "Elevated to level " + std::to_string(result.new_level)};
            }
            return {403, result.message};
        }

        auto decision = access_ctrl_.check_access(
            req.session_token, req.resource_path, req.client_ip, req.timestamp);

        if (decision.allowed) {
            return {200, "Access granted. Remaining tokens: " + 
                    std::to_string(decision.remaining_tokens)};
        }
        return {403, decision.reason};
    }
};
